select relname, relacl::text from pg_class where relname in ('Feature_04_Technical_Indicator','Feature_04_Technical_Indicator_INDEX','Feature04_Calculation_Queue','Price_Stock_Indonesia_IDX');;
select tgname, tgrelid::regclass::text, tgenabled, pg_get_triggerdef(oid) from pg_trigger where not tgisinternal and (tgrelid::regclass::text ilike '%feature_04%' or tgrelid::regclass::text ilike '%price_stock%' or tgrelid::regclass::text ilike '%price_fixed%' or tgname ilike '%feature04%') order by 2,1;;
select proname, md5(prosrc) from pg_proc where proname in ('enqueue_feature04_group','enqueue_feature04_equity_price_row','enqueue_feature04_bond_price_row','feature04_output_columns','request_feature04_retry','feature04_retry_dirty_date','feature04_asset_type','feature04_source_min_date','is_universe_index','open_feature04_fixed_income_run','validate_stock_feature_identity') order by 1
